43	export function getUserId(): string {
44	  let globalConfig = readGlobalConfig();
45	  if (!globalConfig?.id) {
46	    const newId = crypto.randomUUID();
47	    globalConfig = { ...globalConfig, id: newId };
48	    writeGlobalConfig(globalConfig);
49	    return newId;
50	  }
51	
52	  return globalConfig.id;
