67	export async function initializeSourceMapSupport(): Promise<void> {
68	  if (sourceMapSupportInitialized) {
69	    return;
70	  }
71	
72	  sourceMapSupportInitializationPromise ??= (async () => {
73	    try {
74	      const sourceMapSupport = await import('source-map-support');
75	      sourceMapSupport.install();
76	      sourceMapSupportInitialized = true;
77	    } catch {
78	      // Ignore errors. This happens in the production build, because source-map-support is a dev dependency.
79	    } finally {
80	      sourceMapSupportInitializationPromise = null;
81	    }
