145	export const consoleFormatter = winston.format.printf(
146	  (info: winston.Logform.TransformableInfo): string => {
147	    const message = extractMessage(info);
148	
149	    // Call the callback if it exists
150	    if (globalLogCallback) {
151	      globalLogCallback(message);
152	    }
153	
154	    const location = info.location ? `${info.location} ` : '';
155	
156	    if (info.level === 'error') {
157	      return chalk.red(`${location}${message}`);
158	    } else if (info.level === 'warn') {
159	      return chalk.yellow(`${location}${message}`);
160	    } else if (info.level === 'info') {
161	      return `${location}${message}`;
162	    } else if (info.level === 'debug') {
163	      return `${chalk.cyan(location)}${message}`;
164	    }
165	    throw new Error(`Invalid log level: ${info.level}`);
166	  },
167	);
