22	export async function doRedteamRun(options: RedteamRunOptions): Promise<Eval | undefined> {
23	  if (options.verbose) {
24	    setLogLevel('debug');
25	  }
26	  if (options.logCallback) {
27	    setLogCallback(options.logCallback);
28	  }
29	
30	  // Enable live verbose toggle (press 'v' to toggle debug logs)
31	  // Only works in interactive TTY mode, not in CI or web UI
32	  const verboseToggleCleanup = options.logCallback ? null : initVerboseToggle();
33	
34	  let configPath: string = options.config ?? 'promptfooconfig.yaml';
35	
36	  // If output filepath is not provided, locate the out file in the same directory as the config file:
37	  let redteamPath;
38	  if (options.output) {
39	    redteamPath = options.output;
40	  } else {
41	    const configDir = path.dirname(configPath);
42	    redteamPath = path.join(configDir, 'redteam.yaml');
43	  }
44	
45	  // Check API health before proceeding
46	  try {
47	    const healthUrl = getRemoteHealthUrl();
48	    if (healthUrl) {
49	      logger.debug(`Checking Promptfoo API health at ${healthUrl}...`);
50	      const healthResult = await checkRemoteHealth(healthUrl);
51	      if (healthResult.status !== 'OK') {
52	        throw new Error(
53	          `Unable to proceed with redteam: ${healthResult.message}\n` +
54	            'Please check your API configuration or try again later.',
55	        );
56	      }
57	      logger.debug('API health check passed');
58	    }
59	  } catch (error) {
60	    logger.warn(
61	      `API health check failed with error: ${error}.\nPlease check your API configuration or try again later.`,
62	    );
63	  }
64	
65	  if (options.liveRedteamConfig) {
66	    // Write liveRedteamConfig to a temporary file
67	    const filename = `redteam-${Date.now()}.yaml`;
68	    const tmpDir = options.loadedFromCloud ? '' : os.tmpdir();
69	    const tmpFile = path.join(tmpDir, filename);
70	    await fs.mkdir(path.dirname(tmpFile), { recursive: true });
71	    await fs.writeFile(tmpFile, yaml.dump(options.liveRedteamConfig));
72	    redteamPath = tmpFile;
73	    // Do not use default config.
74	    configPath = tmpFile;
75	    logger.debug(`Using live config from ${tmpFile}`);
76	    logger.debug(`Live config: ${JSON.stringify(options.liveRedteamConfig, null, 2)}`);
77	  }
78	
79	  // Generate new test cases
80	  logger.info('Generating test cases...');
81	  const { maxConcurrency, ...passThroughOptions } = options;
82	
83	  let redteamConfig;
84	  const generationStartTime = Date.now();
85	  try {
86	    redteamConfig = await doGenerateRedteam({
87	      ...passThroughOptions,
88	      ...(options.liveRedteamConfig?.commandLineOptions || {}),
89	      ...(maxConcurrency === undefined ? {} : { maxConcurrency }),
90	      config: configPath,
91	      output: redteamPath,
92	      force: options.force,
93	      verbose: options.verbose,
94	      delay: options.delay,
95	      inRedteamRun: true,
96	      abortSignal: options.abortSignal,
97	      progressBar: options.progressBar,
98	    });
99	  } catch (error) {
100	    if (error instanceof PartialGenerationError) {
101	      // Log the detailed error message - this will be visible in CLI and UI (via logCallback)
102	      logger.error(chalk.red('\n' + error.message));
103	      setLogCallback(null);
104	      if (verboseToggleCleanup) {
105	        verboseToggleCleanup();
106	      }
107	      // Re-throw so CLI exits with non-zero code and callers can handle appropriately
108	      throw error;
109	    }
110	    // Re-throw other errors
111	    throw error;
112	  }
113	
114	  const generationDurationMs = Date.now() - generationStartTime;
115	
116	  // Check if redteam.yaml exists before running evaluation
117	  if (!redteamConfig || !(await pathExists(redteamPath))) {
118	    logger.info('No test cases generated. Skipping scan.');
119	    if (verboseToggleCleanup) {
120	      verboseToggleCleanup();
121	    }
122	    return;
123	  }
124	
125	  // Run evaluation
126	  logger.info('Running scan...');
127	  const { defaultConfig } = await loadDefaultConfig();
128	  // Exclude 'description' from options to avoid conflict with Commander's description method
129	  const { description: _description, ...evalOptions } = options;
130	  const evalResult = await doEval(
131	    {
132	      ...evalOptions,
133	      config: [redteamPath],
134	      output: options.output ? [options.output] : undefined,
135	      cache: true,
136	      write: true,
137	      filterPrompts: options.filterPrompts,
138	      filterProviders: options.filterProviders,
139	      filterTargets: options.filterTargets,
140	    },
141	    defaultConfig,
142	    redteamPath,
143	    {
144	      showProgressBar: options.progressBar,
145	      abortSignal: options.abortSignal,
146	      progressCallback: options.progressCallback,
147	    },
148	  );
149	
150	  // Set generation duration on the eval and save
151	  if (evalResult && generationDurationMs >= 0) {
152	    evalResult.setGenerationDurationMs(generationDurationMs);
153	    if (evalResult.persisted) {
154	      await evalResult.save();
155	    }
156	
157	    const totalMs = evalResult.durationMs ?? 0;
158	    const evalMs = evalResult.evaluationDurationMs ?? 0;
159	    logger.info(
160	      chalk.gray(
161	        `Total scan time: ${formatDuration(totalMs / 1000)} (generation: ${formatDuration(generationDurationMs / 1000)}, evaluation: ${formatDuration(evalMs / 1000)})`,
162	      ),
163	    );
164	  }
165	
166	  // Show appropriate completion message based on abort status
167	  // Note: Detailed abort information is already shown in the summary, so we just show a brief message here
168	  // Check if scan was aborted due to target error (efficient DB query, not loading all results)
169	  const hasTargetError = evalResult ? (await evalResult.findTargetErrorStatus()) != null : false;
170	  if (hasTargetError) {
171	    // Abort details already shown in summary - no need to repeat
172	  } else {
173	    logger.info(chalk.green('\nRed team scan complete!'));
174	  }
175	  if (!evalResult?.shared) {
176	    if (options.liveRedteamConfig) {
177	      logger.info(
178	        chalk.blue(
179	          `To view the results, click the ${chalk.bold('View Report')} button or run ${chalk.bold(promptfooCommand('redteam report'))} on the command line.`,
180	        ),
181	      );
182	    } else {
183	      logger.info(
184	        chalk.blue(`To view the results, run ${chalk.bold(promptfooCommand('redteam report'))}`),
185	      );
186	    }
187	  }
188	
189	  // Cleanup
190	  setLogCallback(null);
191	  if (verboseToggleCleanup) {
192	    verboseToggleCleanup();
193	  }
194	  return evalResult;
195	}
