33	    )
34	    .option(
35	      '-o, --output [path]',
36	      'Path to output file for generated tests. Defaults to redteam.yaml in the same directory as the configuration file.',
37	    )
38	    .option('--no-cache', 'Do not read or write results to disk cache', false)
39	    .option('-j, --max-concurrency <number>', 'Maximum number of concurrent API calls', (val) =>
40	      Number.parseInt(val, 10),
41	    )
42	    .option('--delay <number>', 'Delay in milliseconds between API calls', (val) =>
43	      Number.parseInt(val, 10),
44	    )
45	    .option('--remote', 'Force remote inference wherever possible', false)
46	    .option('--force', 'Force generation even if no changes are detected', false)
47	    .option('--no-progress-bar', 'Do not show progress bar')
48	    .option(
49	      '--strict',
50	      'Fail if any plugins fail to generate test cases. By default, warnings are logged but generation continues.',
51	      false,
52	    )
53	    .option(
54	      '--filter-prompts <pattern>',
55	      'Only run tests with prompts whose id or label matches the regex pattern',
56	    )
57	    .option(
58	      '--filter-providers, --filter-targets <providers>',
59	      'Only run tests with these providers (regex match)',
60	    )
61	    .option('-t, --target <id>', 'Cloud provider target ID to run the scan on')
62	    .option('-d, --description <text>', 'Custom description/name for this scan run')
63	    .action(async (opts: RedteamRunOptions) => {
64	      setupEnv(opts.envPath);
65	      telemetry.record('redteam run', {});
66	
67	      if (opts.config && UUID_REGEX.test(opts.config)) {
68	        if (opts.target && !UUID_REGEX.test(opts.target)) {
69	          throw new Error('Invalid target ID, it must be a valid UUID');
70	        }
71	        const configObj = await getConfigFromCloud(opts.config, opts.target);
72	
73	        // backwards compatible for old cloud servers
74	        if (
75	          opts.target &&
76	          UUID_REGEX.test(opts.target) &&
77	          (!configObj.targets || configObj.targets?.length === 0)
78	        ) {
79	          configObj.targets = [{ id: `${CLOUD_PROVIDER_PREFIX}${opts.target}`, config: {} }];
80	        }
81	
82	        // Override description if provided via CLI flag
83	        if (opts.description) {
84	          configObj.description = opts.description;
85	        }
86	
87	        opts.liveRedteamConfig = configObj;
88	        opts.config = undefined;
89	
90	        opts.loadedFromCloud = true;
91	      } else if (opts.target) {
92	        logger.error(
93	          `Target ID (-t) can only be used when -c is used. To use a cloud target inside of a config set the id of the target to ${CLOUD_PROVIDER_PREFIX}${opts.target}. `,
94	        );
95	        process.exitCode = 1;
96	        return;
97	      }
98	
99	      try {
100	        if (opts.remote) {
101	          cliState.remote = true;
102	        }
103	        if (opts.maxConcurrency !== undefined) {
104	          cliState.maxConcurrency = opts.maxConcurrency;
105	        }
106	        await doRedteamRun(opts);
107	      } catch (error) {
108	        if (error instanceof z.ZodError) {
109	          logger.error('Invalid options:');
110	          error.issues.forEach((err: z.ZodIssue) => {
111	            logger.error(`  ${err.path.join('.')}: ${err.message}`);
112	          });
113	        } else if (error instanceof ConfigResolutionError) {
114	          logConfigResolutionError(error);
115	        } else {
116	          logger.error(
117	            `An unexpected error occurred during red team run: ${error instanceof Error ? error.message : String(error)}\n${
118	              error instanceof Error ? error.stack : ''
119	            }`,
120	          );
121	        }
122	        process.exitCode = 1;
123	      } finally {
124	        // Reset cliState to prevent stale state leaking to later commands
125	        cliState.remote = false;
126	        cliState.maxConcurrency = undefined;
127	      }
128	    });
129	
130	  poisonCommand(program);
131	}
